"""Publish the verified Lab 01 step-by-step walkthrough with chapters and capture evidence."""
from pathlib import Path
import json,html,hashlib,shutil
R=Path(__file__).resolve().parents[1];N='managed-agents-lab01-walkthrough';P=R/'presentations'/N;V=R/'videos'/N
TITLE='Lab 01 Step by Step: Session Event Streaming, Offline and Live'
r=json.loads((V/'validation.json').read_text(encoding='utf-8'));assert r['fullVideoAndAudioDecode']=='passed';assert hashlib.sha256((V/r['file']).read_bytes()).hexdigest()==r['sha256']
